{
  "name": "Tango设备通用控制组件",
  "name_en": "Generic Tango Device Component",
  "manufacturer": "Tango Controls",
  "description": "用于在 Tango 控制系统中表示和连接设备资源的通用软件组件，本身不对应单一物理仪器。它基于 Tango 资源定位符（TRL）创建异步设备代理，并可按类注解生成子节点，常用于实验控制软件中组织、连接和测试 Tango 设备对象。",
  "description_en": "A general software component for representing and connecting device resources in the Tango control system; it does not correspond to a single physical instrument. It creates an asynchronous device proxy from a Tango resource locator (TRL) and can generate child nodes from class annotations, making it useful for organizing, connecting, and testing Tango device objects in laboratory control software.",
  "actions": [
    {
      "action_name": "auto-set_trl",
      "description": "设置/定义 Tango 资源定位符（TRL）",
      "description_en": "set/define the Tango resource locator (TRL)"
    },
    {
      "action_name": "auto-create_children_from_annotations",
      "description": "根据类注解创建子设备或属性节点",
      "description_en": "create child devices or attribute nodes from class annotations"
    },
    {
      "action_name": "auto-connect_mock",
      "description": "连接到模拟的 Tango 设备代理",
      "description_en": "connect to a mock Tango device proxy"
    },
    {
      "action_name": "auto-connect_real",
      "description": "连接到真实的 Tango 设备代理",
      "description_en": "connect to a real Tango device proxy"
    }
  ],
  "tag_hints": [
    "Tango Controls",
    "device proxy",
    "asynchronous device connection",
    "TRL resource locator",
    "mock device testing",
    "device abstraction"
  ]
}

